/** provider-name and model-id fragments → icon id. Provider prefix wins;
 *  fragments catch custom endpoints serving known models under other names.
 *  Fragments match in insertion order, so a name that contains a shorter
 *  fragment ("nanogpt" holds "gpt") must come first. */
const PROVIDER_ICON: Record<string, string> = {
  ai2: 'ai2', allenai: 'ai2', olmo: 'ai2', ai21: 'ai21', jamba: 'ai21',
  arcee: 'arcee', baichuan: 'baichuan', bytedance: 'bytedance', seed: 'bytedance',
  cerebras: 'cerebras', ibm: 'ibm', granite: 'ibm', inception: 'inception', mercury: 'inception',
  inflection: 'inflection', microsoft: 'microsoft', phi: 'microsoft',
  nousresearch: 'nousresearch', 'nous-research': 'nousresearch', hermes: 'nousresearch',
  stepfun: 'stepfun', 'step-fun': 'stepfun', tencent: 'tencent', hunyuan: 'tencent',
  xiaomi: 'xiaomimimo', mimo: 'xiaomimimo', zai: 'zai', 'z-ai': 'zai',
  nanogpt: 'nanogpt', 'nano-gpt': 'nanogpt', 'nanogpt-subscription': 'nanogpt',
  anthropic: 'anthropic', claude: 'anthropic',
  openai: 'openai', gpt: 'openai', chatgpt: 'openai', o1: 'openai', o3: 'openai', openrouter: 'openrouter',
  deepseek: 'deepseek',
  google: 'google', gemini: 'google', 'google-vertex': 'google',
  mistral: 'mistral', codestral: 'mistral',
  xai: 'xai', 'x-ai': 'xai', grok: 'xai',
  cohere: 'cohere', command: 'cohere',
  perplexity: 'perplexity', sonar: 'perplexity',
  cometapi: 'cometapi', featherless: 'featherless', infermatic: 'infermatic',
  siliconflow: 'siliconcloud', 'siliconflow-cn': 'siliconcloud',
  groq: 'groq', together: 'togetherai', huggingface: 'huggingface',
  nvidia: 'nvidia', nemotron: 'nvidia',
  ollama: 'ollama-cloud', 'ollama-cloud': 'ollama-cloud',
  deepinfra: 'deepinfra', novita: 'novita', venice: 'venice', zenmux: 'zenmux',
  moonshot: 'moonshotai', kimi: 'moonshotai',
  qwen: 'alibaba', alibaba: 'alibaba', qwq: 'alibaba',
  zhipu: 'zhipuai', glm: 'zhipuai', chatglm: 'zhipuai',
  minimax: 'minimax', meta: 'llama', llama: 'llama',
}

const iconMatchers = Object.entries(PROVIDER_ICON).map(([needle, key]) => ({ key, pattern: new RegExp('(?:^|[^a-z0-9])' + needle + '(?=$|[^a-z]|[0-9])') }))

export function iconKeyForModel(model: string): string | null {
  const s = model.toLowerCase()
  const slash = s.indexOf('/')
  const provider = slash === -1 ? s : s.slice(0, slash)
  const byProvider = PROVIDER_ICON[provider]
  if (byProvider && MODEL_ICONS[byProvider] && !(provider === 'openrouter' && s.slice(slash + 1).includes('/'))) return byProvider
  // a named connection id ("c_<slug>/…") is engine bookkeeping, not a model
  // vendor: its slug can hold a brand fragment ("c_custom-openai-compatible…")
  // that would otherwise label every model the connection serves
  const rest = (provider.startsWith('c_') || provider === 'openrouter') && slash !== -1 ? s.slice(slash + 1) : s
  const nestedSlash = rest.indexOf('/')
  const nestedProvider = nestedSlash === -1 ? rest : rest.slice(0, nestedSlash)
  const nestedIcon = PROVIDER_ICON[nestedProvider]
  if (nestedIcon && MODEL_ICONS[nestedIcon]) return nestedIcon
  for (const { key, pattern } of iconMatchers) {
    if (pattern.test(rest) && MODEL_ICONS[key]) return key
  }
  return null
}
